ALTER TABLE "marketplace_buy_orders_v2" DROP CONSTRAINT "marketplace_buy_orders_v2_kind_valid";--> statement-breakpoint
ALTER TABLE "marketplace_buy_orders_v2" ADD COLUMN "min_power" integer;--> statement-breakpoint
